  public static func add(CHUNK_INDEX: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CHUNK_INDEX, def: 0, at: VT.CHUNK_INDEX) }
  public static func add(CONSECUTIVE_FAILURES: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CONSECUTIVE_FAILURES, def: 0, at: VT.CONSECUTIVE_FAILURES) }
  public static func add(OCCURRED_AT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: OCCURRED_AT, at: VT.OCCURRED_AT) }
  public static func add(RETRY_NOT_BEFORE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RETRY_NOT_BEFORE, at: VT.RETRY_NOT_BEFORE) }
