  public static func createIRM(
    _ fbb: inout FlatBufferBuilder,
    JOB_IDOffset JOB_ID: Offset,
    SEQUENCE: UInt64 = 0,
    PROVIDER_IDOffset PROVIDER_ID: Offset,
    INGESTOR_IDOffset INGESTOR_ID: Offset = Offset(),
    SOURCEOffset SOURCE: Offset,
    STATE: irmJobState = .unspecified,
    RANGE_MODE: irmRangeMode = .unspecified,
    NEXT_OFFSET: UInt64 = 0,
    NEXT_CHUNK_INDEX: UInt32 = 0,
    CHUNK_BYTE_BUDGET: UInt64 = 0,
    DECODE_CONTEXTOffset DECODE_CONTEXT: Offset = Offset(),
    LAST_CHUNKOffset LAST_CHUNK: Offset = Offset(),
    CHUNKS_COMMITTED: UInt32 = 0,
    BYTES_COMMITTED: UInt64 = 0,
    RECORDS_COMMITTED: UInt64 = 0,
    TARGET_STANDARDOffset TARGET_STANDARD: Offset = Offset(),
    RECONCILE_MODEOffset RECONCILE_MODE: Offset = Offset(),
    MERGE_POLICYOffset MERGE_POLICY: Offset = Offset(),
    FAULTOffset FAULT: Offset = Offset(),
    CREATED_ATOffset CREATED_AT: Offset = Offset(),
    STARTED_ATOffset STARTED_AT: Offset = Offset(),
    UPDATED_ATOffset UPDATED_AT: Offset,
    COMPLETED_ATOffset COMPLETED_AT: Offset = Offset(),
    EXPIRES_ATOffset EXPIRES_AT: Offset = Offset(),
    TAGSVectorOffset TAGS: Offset = Offset(),
    NOTESOffset NOTES: Offset = Offset()
  ) -> Offset {
    let __start = IRM.startIRM(&fbb)
    IRM.add(JOB_ID: JOB_ID, &fbb)
    IRM.add(SEQUENCE: SEQUENCE, &fbb)
    IRM.add(PROVIDER_ID: PROVIDER_ID, &fbb)
    IRM.add(INGESTOR_ID: INGESTOR_ID, &fbb)
    IRM.add(SOURCE: SOURCE, &fbb)
    IRM.add(STATE: STATE, &fbb)
    IRM.add(RANGE_MODE: RANGE_MODE, &fbb)
    IRM.add(NEXT_OFFSET: NEXT_OFFSET, &fbb)
    IRM.add(NEXT_CHUNK_INDEX: NEXT_CHUNK_INDEX, &fbb)
    IRM.add(CHUNK_BYTE_BUDGET: CHUNK_BYTE_BUDGET, &fbb)
    IRM.add(DECODE_CONTEXT: DECODE_CONTEXT, &fbb)
    IRM.add(LAST_CHUNK: LAST_CHUNK, &fbb)
    IRM.add(CHUNKS_COMMITTED: CHUNKS_COMMITTED, &fbb)
    IRM.add(BYTES_COMMITTED: BYTES_COMMITTED, &fbb)
    IRM.add(RECORDS_COMMITTED: RECORDS_COMMITTED, &fbb)
    IRM.add(TARGET_STANDARD: TARGET_STANDARD, &fbb)
    IRM.add(RECONCILE_MODE: RECONCILE_MODE, &fbb)
    IRM.add(MERGE_POLICY: MERGE_POLICY, &fbb)
    IRM.add(FAULT: FAULT, &fbb)
    IRM.add(CREATED_AT: CREATED_AT, &fbb)
    IRM.add(STARTED_AT: STARTED_AT, &fbb)
    IRM.add(UPDATED_AT: UPDATED_AT, &fbb)
    IRM.add(COMPLETED_AT: COMPLETED_AT, &fbb)
    IRM.add(EXPIRES_AT: EXPIRES_AT, &fbb)
    IRM.addVectorOf(TAGS: TAGS, &fbb)
    IRM.add(NOTES: NOTES, &fbb)
    return IRM.endIRM(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.JOB_ID, fieldName: "JOB_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SEQUENCE, fieldName: "SEQUENCE", required: false, type: UInt64.self)
    try _v.visit(field: VT.PROVIDER_ID, fieldName: "PROVIDER_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.INGESTOR_ID, fieldName: "INGESTOR_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SOURCE, fieldName: "SOURCE", required: true, type: ForwardOffset<IRMSource>.self)
    try _v.visit(field: VT.STATE, fieldName: "STATE", required: false, type: irmJobState.self)
    try _v.visit(field: VT.RANGE_MODE, fieldName: "RANGE_MODE", required: false, type: irmRangeMode.self)
    try _v.visit(field: VT.NEXT_OFFSET, fieldName: "NEXT_OFFSET", required: false, type: UInt64.self)
    try _v.visit(field: VT.NEXT_CHUNK_INDEX, fieldName: "NEXT_CHUNK_INDEX", required: false, type: UInt32.self)
    try _v.visit(field: VT.CHUNK_BYTE_BUDGET, fieldName: "CHUNK_BYTE_BUDGET", required: false, type: UInt64.self)
    try _v.visit(field: VT.DECODE_CONTEXT, fieldName: "DECODE_CONTEXT", required: false, type: ForwardOffset<IRMDecodeContext>.self)
    try _v.visit(field: VT.LAST_CHUNK, fieldName: "LAST_CHUNK", required: false, type: ForwardOffset<IRMChunk>.self)
    try _v.visit(field: VT.CHUNKS_COMMITTED, fieldName: "CHUNKS_COMMITTED", required: false, type: UInt32.self)
    try _v.visit(field: VT.BYTES_COMMITTED, fieldName: "BYTES_COMMITTED", required: false, type: UInt64.self)
    try _v.visit(field: VT.RECORDS_COMMITTED, fieldName: "RECORDS_COMMITTED", required: false, type: UInt64.self)
    try _v.visit(field: VT.TARGET_STANDARD, fieldName: "TARGET_STANDARD", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.RECONCILE_MODE, fieldName: "RECONCILE_MODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.MERGE_POLICY, fieldName: "MERGE_POLICY", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FAULT, fieldName: "FAULT", required: false, type: ForwardOffset<IRMFault>.self)
    try _v.visit(field: VT.CREATED_AT, fieldName: "CREATED_AT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.STARTED_AT, fieldName: "STARTED_AT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.UPDATED_AT, fieldName: "UPDATED_AT", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.COMPLETED_AT, fieldName: "COMPLETED_AT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.EXPIRES_AT, fieldName: "EXPIRES_AT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.TAGS, fieldName: "TAGS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.NOTES, fieldName: "NOTES", required: false, type: ForwardOffset<String>.self)
